    const int nfr = (C4 / 16) * KS * 32;
    if (i >= nfr) return;
    const int lane = i & 31, f = i >> 5, mt = f / KS, ks = f - mt * KS;
    const int g = lane >> 2, t = lane & 3;
    const int r0 = mt * 16 + g, r1 = r0 + 8, c0 = ks * 16 + 2 * t, c2 = c0 + 8;
    auto pk = [&](int r, int c) {
      const float a = __ldg(p.w1 + (size_t)r * C + c) * __ldg(p.lnw + c);
      const float b = __ldg(p.w1 + (size_t)r * C + c + 1) * __ldg(p.lnw + c + 1);
      return h2u(__floats2half2_rn(a, b));
    };
    uint4 v; v.x = pk(r0, c0); v.y = pk(r1, c0); v.z = pk(r0, c2); v.w = pk(r1, c2);
    reinterpret_cast<uint4*>(p.w1f)[i] = v;
  } else {
    const int k = (blockIdx.x - nfragblk) * 8 + (threadIdx.x >> 5), lane = threadIdx.x & 31;
    if (k >= C4) return;
    const float* wr = p.w1 + (size_t)k * C;
    float u = 0.f, v = 0.f;
    for (int c = lane; c < C; c += 32) {
      const float w = __ldg(wr + c);
      u += __half2float(__float2half_rn(w * __ldg(p.lnw + c)));
      v = fmaf(w, __ldg(p.lnb + c), v);
    }
    u = g_wsum(u); v = g_wsum(v);
    if (lane == 0) { p.uv[2 * k] = u; p.uv[2 * k + 1] = v + __ldg(p.b1 + k); }
  }
}

template <int C, int R, int W, int NWARP, int MG>
struct P1Cfg {
  static constexpr int C4 = 4 * C, T = R * W, LDT = T + 8, QW = W / 4, NT = NWARP * 32, KS = C / 16, MT = C4 / 16;
  static constexpr int SM_W1F = MT * KS * 32 * 16;
  static constexpr int SM_D = C * LDT * 2;
  static constexpr int SM_ST = T * 8;
  static constexpr int SM_UV = C4 * 8;
  static constexpr int SM_PS = C4 * 4;
  static constexpr int SMEM = SM_W1F + SM_D + SM_ST + SM_UV + SM_PS;
};

template <int C, int R, int W, int NWARP, int MG>
__global__ void __launch_bounds__(NWARP * 32, 1) g_pass1(GParams p) {
  using Cf = P1Cfg<C, R, W, NWARP, MG>;
  constexpr int C4 = Cf::C4, T = Cf::T, LDT = Cf::LDT, QW = Cf::QW, NT = Cf::NT, KS = Cf::KS;
  constexpr int P = T / 2, S = NT / P;
  static_assert(NT % P == 0 && (S & (S - 1)) == 0 && S <= 32, "stats split");
  constexpr int NMG = C4 / (16 * MG), NCH = T / 32;
  static_assert(C4 % (16 * MG) == 0 && T % 32 == 0 && W % 4 == 0 && C % 16 == 0, "tiles");
  extern __shared__ __align__(16) unsigned char sm[];
  uint4* w1s = reinterpret_cast<uint4*>(sm);
  __half* ds = reinterpret_cast<__half*>(sm + Cf::SM_W1F);
  float2* sts = reinterpret_cast<float2*>(sm + Cf::SM_W1F + Cf::SM_D);
  float2* uvs = reinterpret_cast<float2*>(sm + Cf::SM_W1F + Cf::SM_D + Cf::SM_ST);
  float* pss = reinterpret_cast<float*>(sm + Cf::SM_W1F + Cf::SM_D + Cf::SM_ST + Cf::SM_UV);
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  const int H = p.H, HW = p.HW, K2 = p.K2, TPI = p.TPI;
  __half* hg = reinterpret_cast<__half*>(p.h);

  for (int i = tid; i < Cf::SM_W1F / 16; i += NT) w1s[i] = reinterpret_cast<const uint4*>(p.w1f)[i];
  for (int i = tid; i < C4; i += NT) { uvs[i] = reinterpret_cast<const float2*>(p.uv)[i]; pss[i] = 0.f; }
  __syncthreads();

  int prev = -1;
#pragma unroll 1
  for (int tile = blockIdx.x; tile < p.ntiles; tile += gridDim.x) {
    const int b = tile / TPI, rb = tile - b * TPI, h0 = rb * R, hw0 = h0 * W;
    if (prev >= 0)
      for (int k = tid; k < C4; k += NT) { p.part[(size_t)prev * C4 + k] = pss[k]; pss[k] = 0.f; }
    prev = tile;

    // ---- depthwise 7x7 conv: item = (channel, 4-column quad), R rows x 4 cols per thread
#pragma unroll 1
    for (int it = tid; it < C * QW; it += NT) {
      const int c = it / QW, q = it - c * QW, w0 = 4 * q;
      const float* xc = p.x + (size_t)(b * C + c) * HW;
      float wt[49];
#pragma unroll
      for (int i = 0; i < 49; i++) wt[i] = __ldg(p.dww + c * 49 + i);
      const float bias = __ldg(p.dwb + c);
      float acc[R][4];
#pragma unroll
      for (int r = 0; r < R; r++)
#pragma unroll
        for (int cc = 0; cc < 4; cc++) acc[r][cc] = 0.f;
#pragma unroll
      for (int ir = 0; ir < R + 6; ir++) {
        const int hh = h0 - 3 + ir;
        float4 L = make_float4(0.f, 0.f, 0.f, 0.f), M = L, Rg = L;
        if (hh >= 0 && hh < H) {
          const float* rp = xc + hh * W + w0;
          if (q > 0) L = __ldg(reinterpret_cast<const float4*>(rp - 4));
          M = __ldg(reinterpret_cast<const float4*>(rp));
          if (q < QW - 1) Rg = __ldg(reinterpret_cast<const float4*>(rp + 4));
        }
        const float v[10] = {L.y, L.z, L.w, M.x, M.y, M.z, M.w, Rg.x, Rg.y, Rg.z};
#pragma unroll
        for (int r = 0; r < R; r++) {
          const int ki = ir - r;
          if (ki >= 0 && ki < 7) {
#pragma unroll
            for (int j = 0; j < 7; j++)
#pragma unroll
              for (int cc = 0; cc < 4; cc++) acc[r][cc] = fmaf(v[cc + j], wt[ki * 7 + j], acc[r][cc]);
          }
        }
      }
#pragma unroll
      for (int r = 0; r < R; r++) {
        uint2 u;
        u.x = h2u(__floats2half2_rn(acc[r][0] + bias, acc[r][1] + bias));
        u.y = h2u(__floats2half2_rn(acc[r][2] + bias, acc[r][3] + bias));
        *reinterpret_cast<uint2*>(ds + c * LDT + r * W + w0) = u;
      }
    }
    __syncthreads();

    // ---- per-token LayerNorm statistics of the fp16 d tile (2 tokens per thread, S channel slices)
    {
      const int pp = tid / S, s = tid - pp * S;
      float s1a = 0.f, s2a = 0.f, s1b = 0.f, s2b = 0.f;
#pragma unroll 8
      for (int c = s; c < C; c += S) {
        const float2 f = __half22float2(*reinterpret_cast<const __half2*>(ds + c * LDT + 2 * pp));
        s1a += f.x; s2a = fmaf(f.x, f.x, s2a); s1b += f.y; s2b = fmaf(f.y, f.y, s2b);
      }
#pragma unroll
      for (int o = 1; o < S; o <<= 1) {
        s1a += __shfl_xor_sync(0xffffffffu, s1a, o); s2a += __shfl_xor_sync(0xffffffffu, s2a, o);
        s1b += __shfl_xor_sync(0xffffffffu, s1b, o); s2b += __shfl_xor_sync(0xffffffffu, s2b, o);
      }
      if (s == 0) {
        constexpr float inv = 1.f / (float)C;
        const float m0 = s1a * inv, m1 = s1b * inv;
        const float r0 = rsqrtf(fmaxf(s2a * inv - m0 * m0, 0.f) + p.ln_eps);
        const float r1 = rsqrtf(fmaxf(s2b * inv - m1 * m1, 0.f) + p.ln_eps);
        *reinterpret_cast<float4*>(sts + 2 * pp) = make_float4(r0, r0 * m0, r1, r1 * m1);
        __half* ha = hg + ((size_t)b * K2 + C4) * HW + hw0 + 2 * pp;
        const uint32_t one = h2u(__floats2half2_rn(1.f, 1.f));
#pragma unroll
        for (int j = 0; j < 8; j++) *reinterpret_cast<uint32_t*>(ha + (size_t)j * HW) = j < 2 ? one : 0u;
      }
    }
    __syncthreads();

    // ---- GEMM1 (mma.sync, A = W1' frags in smem, B = d tile) + LN fold + GELU + sumsq + fp16 hidden
    {
      const int g = lane >> 2, t4 = lane & 3;
#pragma unroll 1
      for (int wt = warp; wt < NMG * NCH; wt += NWARP) {
        const int mg = wt / NCH, nc = wt - mg * NCH;
        float acc[MG][4][4];
#pragma unroll
        for (int m = 0; m < MG; m++)
#pragma unroll
          for (int n = 0; n < 4; n++)
#pragma unroll
            for (int e = 0; e < 4; e++) acc[m][n][e] = 0.f;
#pragma unroll
        for (int ks = 0; ks < KS; ks++) {
          uint32_t bf[2][4];
#pragma unroll
          for (int pr = 0; pr < 2; pr++) {
            const int mi = lane >> 3, rr = lane & 7;
            ldsm_x4_t(bf[pr], ds + (ks * 16 + (mi & 1) * 8 + rr) * LDT + nc * 32 + pr * 16 + (mi >> 1) * 8);
          }
#pragma unroll
          for (int m = 0; m < MG; m++) {
            const uint4 a = w1s[((mg * MG + m) * KS + ks) * 32 + lane];
#pragma unroll
            for (int n = 0; n < 4; n++) mma16816(acc[m][n], a, bf[n >> 1][(n & 1) * 2], bf[n >> 1][(n & 1) * 2 + 1]);
          }
        }
#pragma unroll
        for (int m = 0; m < MG; m++) {
          const int k0 = (mg * MG + m) * 16 + g, k1 = k0 + 8;
          const float2 uv0 = uvs[k0], uv1 = uvs[k1];
          float ss0 = 0.f, ss1 = 0.f;
          __half* hp0 = hg + ((size_t)b * K2 + k0) * HW + hw0;
          __half* hp1 = hp0 + (size_t)8 * HW;
#pragma unroll
          for (int n = 0; n < 4; n++) {
            const int tok = nc * 32 + n * 8 + 2 * t4;
            const float4 st = *reinterpret_cast<const float4*>(sts + tok);
            const float g00 = gelu_erf(fmaf(st.x, acc[m][n][0], fmaf(-st.y, uv0.x, uv0.y)));
            const float g01 = gelu_erf(fmaf(st.z, acc[m][n][1], fmaf(-st.w, uv0.x, uv0.y)));
            const float g10 = gelu_erf(fmaf(st.x, acc[m][n][2], fmaf(-st.y, uv1.x, uv1.y)));
            const float g11 = gelu_erf(fmaf(st.z, acc[m][n][3], fmaf(-st.w, uv1.x, uv1.y)));
            ss0 = fmaf(g00, g00, fmaf(g01, g01, ss0));
            ss1 = fmaf(g10, g10, fmaf(g11, g11, ss1));
            *reinterpret_cast<uint32_t*>(hp0 + tok) = h2u(__floats2half2_rn(g00, g01));
            *reinterpret_cast<uint32_t*>(hp1 + tok) = h2u(__floats2half2_rn(g10, g11));
          }
          ss0 += __shfl_xor_sync(0xffffffffu, ss0, 1); ss0 += __shfl_xor_sync(0xffffffffu, ss0, 2);
          ss1 += __shfl_xor_sync(0xffffffffu, ss1, 1); ss1 += __shfl_xor_sync(0xffffffffu, ss1, 2);
          if (t4 == 0) { atomicAdd(pss + k0, ss0); atomicAdd(pss + k1, ss1); }
        }
      }
    }
    __syncthreads();
  }
  if (prev >= 0)
    for (int k = tid; k < C4; k += NT) p.part[(size_t)prev * C4 + k] = pss[k];
}

// K3: GRN scale per image -> W2_b = fp16(W2 * s_b) [c][K2], b2' = W2.gb + b2 as hi/lo columns C4, C4+1
__global__ void __launch_bounds__(512) g_grn(GParams p) {
  extern __shared__ __align__(16) float gsm[];
  const int C = p.C, C4 = p.C4, K2 = p.K2, TPI = p.TPI;
  float* sc = gsm; float* red = gsm + C4;
  const int b = blockIdx.x, tid = threadIdx.x, lane = tid & 31, warp = tid >> 5;
  float loc = 0.f;
  for (int k = tid; k < C4; k += 512) {
    const float* pp = p.part + (size_t)b * TPI * C4 + k;
    float s0 = 0.f, s1 = 0.f, s2 = 0.f, s3 = 0.f;
    int r = 0;
    for (; r + 4 <= TPI; r += 4) {
      s0 += pp[(size_t)r * C4]; s1 += pp[(size_t)(r + 1) * C4];
      s2 += pp[(size_t)(r + 2) * C4]; s3 += pp[(size_t)(r + 3) * C4];
    }
    for (; r < TPI; r++) s0 += pp[(size_t)r * C4];
    const float gf = sqrtf((s0 + s1) + (s2 + s3));
    sc[k] = gf; loc += gf;
  }
  loc = g_wsum(loc);
  if (lane == 0) red[warp] = loc;
  __syncthreads();
  if (warp == 0) {
    float v = lane < 16 ? red[lane] : 0.f;
    v = g_wsum(v);
    if (lane == 0) red[32] = 1.f / (v / (float)C4 + p.eps);
  }
  __syncthreads();
  const float inv = red[32];
  for (int k = tid; k < C4; k += 512) sc[k] = fmaf(__ldg(p.gw + k) * sc[k], inv, 1.f);
  __syncthreads();
  __half* w2b = reinterpret_cast<__half*>(p.w2b) + (size_t)b * C * K2;
  for (int c = warp; c < C; c += 16) {
    const float* wr = p.w2 + (size_t)c * C4;
    float dot = 0.f;
    for (int k = lane * 4; k < C4; k += 128) {
      const float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
      const float4 gv = __ldg(reinterpret_cast<const float4*>(p.gb + k));
      const float4 s = *reinterpret_cast<const float4*>(sc + k);
      dot = fmaf(w.x, gv.x, dot); dot = fmaf(w.y, gv.y, dot); dot = fmaf(w.z, gv.z, dot); dot = fmaf(w.w, gv.w, dot);
      uint2 u;
      u.x = h2u(__floats2half2_rn(w.x * s.x, w.y * s.y));
      u.y = h2u(__floats2half2_rn(w.z * s.z, w.w * s.w));
      *reinterpret_cast<uint2*>(w2b + (size_t)c * K2 + k) = u;
    }
    dot = g_wsum(dot);
    if (lane == 0) {
      dot += __ldg(p.b2 + c);
      const __half hh = __float2half_rn(dot);
      const __half hl = __float2half_rn(dot - __half2float(hh));
      *reinterpret_cast<uint4*>(w2b + (size_t)c * K2 + C4) = make_uint4(h2u(__halves2half2(hh, hl)), 0u, 0u, 0u);
    }
  }
}

// ---------------------------------------------------------------- host
extern "C" int g_rows_per_tile(int C, int H, int W) {
  if (C == 96 && H == 112 && W == 112) return 4;
  if (C == 128 && H == 64 && W == 64) return 4;
  if (C == 96 && H == 56 && W == 56) return 4;
  return 0;
}

static int g_num_sms() {
  static int n = 0;
  if (n == 0) { int dev = 0; cudaGetDevice(&dev); cudaDeviceGetAttribute(&n, cudaDevAttrMultiProcessorCount, dev); }
  return n;
}

template <int C, int R, int W, int NWARP, int MG>
static const char* launch_p1(const GParams& p, cudaStream_t s) {
  using Cf = P1Cfg<C, R, W, NWARP, MG>;
  static bool init = false;
  if (!init) {
    cudaError_t e = cudaFuncSetAttribute(g_pass1<C, R, W, NWARP, MG>, cudaFuncAttributeMaxDynamicSharedMemorySize, Cf::SMEM);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    init = true;
  }
  const int grid = p.ntiles < g_num_sms() ? p.ntiles : g_num_sms();
  g_pass1<C, R, W, NWARP, MG><<<grid, NWARP * 32, Cf::SMEM, s>>>(p);
  return nullptr;
}

static cublasLtHandle_t g_lt() {
  static cublasLtHandle_t h = nullptr;
  if (!h) cublasLtCreate(&h);
  return h;
}

#define LTCHK(x) do { if ((x) != CUBLAS_STATUS_SUCCESS) { err = "cublasLt: " #x; goto done; } } while (0)
static const char* g_gemm2(const GParams& p, void* ws, size_t wsb, cudaStream_t s) {
  static std::map<std::tuple<int, int, int>, cublasLtMatmulHeuristicResult_t> cache;
  const char* err = nullptr;
  cublasLtHandle_t lt = g_lt();
  cublasLtMatmulDesc_t op = nullptr;
  cublasLtMatrixLayout_t la = nullptr, lb = nullptr, lc = nullptr;
  const cublasOperation_t tn = CUBLAS_OP_N;
  const int32_t bc = p.B;
  const int64_t sa = (int64_t)p.K2 * p.HW, sb = (int64_t)p.C * p.K2, scd = (int64_t)p.C * p.HW;
  const float alpha = 1.f, beta = 1.f;
  auto key = std::make_tuple(p.B, p.C, p.HW);
  LTCHK(cublasLtMatmulDescCreate(&op, CUBLAS_COMPUTE_32F, CUDA_R_32F));
  LTCHK(cublasLtMatmulDescSetAttribute(op, CUBLASLT_MATMUL_DESC_TRANSA, &tn, sizeof(tn)));
  LTCHK(cublasLtMatmulDescSetAttribute(op, CUBLASLT_MATMUL_DESC_TRANSB, &tn, sizeof(tn)));
  LTCHK(cublasLtMatrixLayoutCreate(&la, CUDA_R_16F, p.HW, p.K2, p.HW));
  LTCHK(cublasLtMatrixLayoutCreate(&lb, CUDA_R_16F, p.K2, p.C, p.K2));
  LTCHK(cublasLtMatrixLayoutCreate(&lc, CUDA_R_32F, p.HW, p.C, p.HW));
  LTCHK(cublasLtMatrixLayoutSetAttribute(la, CUBLASLT_MATRIX_LAYOUT_BATCH_COUNT, &bc, sizeof(bc)));
  LTCHK(cublasLtMatrixLayoutSetAttribute(lb, CUBLASLT_MATRIX_LAYOUT_BATCH_COUNT, &bc, sizeof(bc)));
  LTCHK(cublasLtMatrixLayoutSetAttribute(lc, CUBLASLT_MATRIX_LAYOUT_BATCH_COUNT, &bc, sizeof(bc)));
  LTCHK(cublasLtMatrixLayoutSetAttribute(la, CUBLASLT_MATRIX_LAYOUT_STRIDED_BATCH_OFFSET, &sa, sizeof(sa)));
  LTCHK(cublasLtMatrixLayoutSetAttribute(lb, CUBLASLT_MATRIX_LAYOUT_STRIDED_BATCH_OFFSET, &sb, sizeof(sb)));
  LTCHK(cublasLtMatrixLayoutSetAttribute(lc, CUBLASLT_MATRIX_LAYOUT_STRIDED_BATCH_OFFSET, &scd, sizeof(scd)));
  if (cache.find(key) == cache.end()) {
    cublasLtMatmulPreference_t pref = nullptr;
    const uint64_t wsl = wsb;
    cublasLtMatmulHeuristicResult_t res;
    int n = 0;
    LTCHK(cublasLtMatmulPreferenceCreate(&pref));
    cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &wsl, sizeof(wsl));
    const cublasStatus_t st = cublasLtMatmulAlgoGetHeuristic(lt, op, la, lb, lc, lc, pref, 1, &res, &n);
    cublasLtMatmulPreferenceDestroy(pref);
    if (st != CUBLAS_STATUS_SUCCESS || n == 0) { err = "cublasLt: no heuristic for GEMM2"; goto done; }
    cache[key] = res;
  }
  LTCHK(cublasLtMatmul(lt, op, &alpha, p.h, la, p.w2b, lb, &beta, p.x, lc, p.out, lc, &cache[key].algo, ws, wsb, s));
done:
  if (la) cublasLtMatrixLayoutDestroy(la);
  if (lb) cublasLtMatrixLayoutDestroy(lb);
  if (lc) cublasLtMatrixLayoutDestroy(lc);
  if (op) cublasLtMatmulDescDestroy(op);
  return err;
}

extern "C" const char* g_launch(GParams p, void* ltws, size_t ltws_bytes, int mask, void* stream_v) {
  cudaStream_t s = (cudaStream_t)stream_v;
  const int R = g_rows_per_tile(p.C, p.H, p.W);
  if (R == 0) return "unsupported shape";
  p.HW = p.H * p.W; p.C4 = 4 * p.C; p.K2 = p.C4 + 8; p.TPI = p.H / R; p.ntiles = p.B * p.TPI;
  const char* err = nullptr;
  if (mask & 1) {
    const int nfr = (p.C4 / 16) * (p.C / 16) * 32;
    const int nfb = (nfr + 255) / 256, nub = (p.C4 + 7) / 8;
    g_prep<<<nfb + nub, 256, 0, s>>>(p, nfb);
  }
  if (mask & 2) {
    if (p.C == 96 && p.W == 112) err = launch_p1<96, 4, 112, 14, 3>(p, s);
    else if (p.C == 128 && p.W == 64) err = launch_p1<128, 4, 64, 16, 2>(p, s);
    else if (p.C == 96 && p.W == 56) err = launch_p1<96, 4, 56, 14, 3>(p, s);
    if (err) return err;
  }
  if (mask & 4) g_grn<<<p.B, 512, (p.C4 + 64) * 4, s>>>(p);
  if (mask & 8) { err = g_gemm2(p, ltws, ltws_bytes, s); if (err) return err; }
  cudaError_t e = cudaGetLastError();
  return e == cudaSuccess ? nullptr : cudaGetErrorString(e);
}
'''
BIND = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <stdexcept>
struct GParams {
