extern "C" int g_rows_per_tile(int C, int H, int W);
extern "C" const char* g_launch(GParams p, void* ltws, size_t ltws_bytes, int mask, void* stream);
static inline size_t al(size_t v) { return (v + 255) & ~(size_t)255; }
void run_dbg(torch::Tensor x, torch::Tensor dww, torch::Tensor dwb, torch::Tensor lnw, torch::Tensor lnb, torch::Tensor w1,
