  float loc = 0.f;
  for (int k = tid; k < C4; k += 512) {
    const float* pp = p.part + (size_t)b * TPI * C4 + k;
    float s[8] = {0.f, 0.f, 0.f, 0.f, 0.f, 0.f, 0.f, 0.f};
    int r = 0;
    for (; r + 8 <= TPI; r += 8) {
#pragma unroll
      for (int u = 0; u < 8; u++) s[u] += __ldcg(pp + (size_t)(r + u) * C4);
    }
    for (; r < TPI; r++) s[0] += __ldcg(pp + (size_t)r * C4);
    const float gf = sqrtf(((s[0] + s[1]) + (s[2] + s[3])) + ((s[4] + s[5]) + (s[6] + s[7])));
    sc[k] = gf; loc += gf;
  }
  loc = g_wsum(loc);
  if (lane == 0) red[warp] = loc;
  __syncthreads();
