    float v = lane < 16 ? red[lane] : 0.f;
    v = g_wsum(v);
    if (lane == 0) red[32] = 1.f / (v / (float)C4 + p.eps);
  }
  __syncthreads();
  const float inv = red[32];
  for (int k = tid; k < C4; k += 512) sc[k] = fmaf(__ldg(p.gw + k) * sc[k], inv, 1.f);
