  if (mask & 2) {
    if (p.C == 96 && p.W == 112) err = p.variant ? launch_p1<96, 2, 112, 7, 9, 3, true>(p, s)
                                                 : launch_p1<96, 2, 112, 7, 7, 3, true>(p, s);
    else if (p.C == 128 && p.W == 64) err = launch_p1<128, 2, 64, 8, 8, 2, false>(p, s);
    else if (p.C == 96 && p.W == 56) err = p.variant ? launch_p1<96, 4, 56, 7, 9, 3, true>(p, s)
                                                     : launch_p1<96, 4, 56, 7, 7, 3, true>(p, s);
    if (err) return err;
  }
  if (mask & 4) g_grn<<<dim3(p.B, (p.C + 15) / 16), 512, (p.C4 + 64) * 4, s>>>(p);
  if (mask & 8) { err = g_gemm2(p, ltws, ltws_bytes, s); if (err) return err; }
  cudaError_t e = cudaGetLastError();
  return e == cudaSuccess ? nullptr : cudaGetErrorString(e);
}
