    int i = 0;
#pragma unroll 1
    for (int tile = blockIdx.x; tile < p.ntiles; tile += gridDim.x, i++) {
      const int buf = i & 1;
      const int b = tile / TPI, rb = tile - b * TPI, h0 = rb * R, hw0 = h0 * W;
      if (i >= 2) nbar_sync(3 + buf, NT);  // GEMM warps are done with this buffer
      __half* ds = dsb + buf * (C * LDT);
