            }
          }
        }
#pragma unroll
        for (int r = 0; r < 2; r++) {
          const int t0 = (r0 + r) * W + w0;  // multiple of 8: q fixed, n = 0..3
          __half* dp = ds + c * LDT + (t0 & ~31) + (((t0 >> 3) & 3) << 1);
#pragma unroll
          for (int n = 0; n < 4; n++)
